   126→// runExplainCheckpoint explains a specific checkpoint.
   127→func runExplainCheckpoint(w io.Writer, checkpointIDPrefix string, noPager, verbose, full bool) error {
   128→	repo, err := openRepository()
   129→	if err != nil {
   130→		return fmt.Errorf("not a git repository: %w", err)
   131→	}
   132→
   133→	store := checkpoint.NewGitStore(repo)
   134→
   135→	// Find checkpoint by prefix
   136→	committed, err := store.ListCommitted(context.Background())
   137→	if err != nil {
   138→		return fmt.Errorf("failed to list checkpoints: %w", err)
   139→	}
   140→
   141→	var fullCheckpointID string
   142→	for _, info := range committed {
   143→		if strings.HasPrefix(info.CheckpointID, checkpointIDPrefix) {
   144→			fullCheckpointID = info.CheckpointID
   145→			break
   146→		}
   147→	}
   148→
   149→	if fullCheckpointID == "" {
   150→		return fmt.Errorf("checkpoint not found: %s", checkpointIDPrefix)
   151→	}
   152→
   153→	// Load checkpoint data
   154→	result, err := store.ReadCommitted(context.Background(), fullCheckpointID)
   155→	if err != nil {
   156→		return fmt.Errorf("failed to read checkpoint: %w", err)
   157→	}
   158→
   159→	// Format and output
   160→	output := formatCheckpointOutput(result, fullCheckpointID, verbose, full)
   161→
   162→	if noPager {
   163→		fmt.Fprint(w, output)
   164→	} else {
   165→		outputWithPager(w, output)
   166→	}
   167→
   168→	return nil
   169→}
