   209→	// Get source ref (metadata branch + commit) for this session
   210→	sourceRef := strat.GetSessionMetadataRef(session.ID)
   211→
   212→	// Gather checkpoint details
   213→	checkpointDetails := gatherCheckpointDetails(strat, session)
   214→
   215→	// For strategies like shadow where active sessions may not have checkpoints,
   216→	// try to get the current session transcript directly
   217→	if len(checkpointDetails) == 0 && len(session.Checkpoints) == 0 {
   218→		checkpointDetails = gatherCurrentSessionDetails(strat, session)
   219→	}
   220→
   221→	// Format output
