   234→// gatherCurrentSessionDetails attempts to get transcript info for sessions without checkpoints.
   235→// This handles strategies like shadow where active sessions may not have checkpoint commits.
   236→func gatherCurrentSessionDetails(strat strategy.Strategy, session *strategy.Session) []checkpointDetail {
   237→	// Try to get transcript via GetSessionContext which reads from metadata branch
   238→	// For shadow, we can read the transcript from the same location pattern
   239→	contextContent := strat.GetSessionContext(session.ID)
   240→	if contextContent == "" {
   241→		return nil
   242→	}
   243→
   244→	// Parse the context.md to extract the last prompt/summary
   245→	// Context.md typically has sections like "# Prompt\n...\n## Summary\n..."
   246→	detail := checkpointDetail{
   247→		Index:     1,
   248→		Timestamp: session.StartTime,
   249→		Message:   "Current session",
   250→	}
   251→
   252→	// Try to extract prompt and summary from context.md
   253→	lines := strings.Split(contextContent, "\n")
   254→	var inPrompt, inSummary bool
   255→	var promptLines, summaryLines []string
   256→
   257→	for _, line := range lines {
   258→		trimmed := strings.TrimSpace(line)
   259→		if strings.HasPrefix(trimmed, "# ") && strings.Contains(strings.ToLower(trimmed), "prompt") {
   260→			inPrompt = true
   261→			inSummary = false
   262→			continue
   263→		}
   264→		if strings.HasPrefix(trimmed, "## ") && strings.Contains(strings.ToLower(trimmed), "summary") {
   265→			inPrompt = false
   266→			inSummary = true
   267→			continue
   268→		}
   269→		if strings.HasPrefix(trimmed, "## ") || strings.HasPrefix(trimmed, "# ") {
   270→			inPrompt = false
   271→			inSummary = false
   272→			continue
   273→		}
   274→
   275→		if inPrompt {
   276→			promptLines = append(promptLines, line)
   277→		} else if inSummary {
   278→			summaryLines = append(summaryLines, line)
   279→		}
   280→	}
   281→
   282→	var inter interaction
   283→	if len(promptLines) > 0 {
   284→		inter.Prompt = strings.TrimSpace(strings.Join(promptLines, "\n"))
   285→	}
   286→	if len(summaryLines) > 0 {
   287→		inter.Responses = []string{strings.TrimSpace(strings.Join(summaryLines, "\n"))}
   288→	}
   289→
   290→	// If we couldn't parse structured content, show the raw context
   291→	if inter.Prompt == "" && len(inter.Responses) == 0 {
   292→		inter.Responses = []string{contextContent}
   293→	}
   294→
   295→	if inter.Prompt != "" || len(inter.Responses) > 0 {
   296→		detail.Interactions = []interaction{inter}
   297→	}
   298→
   299→	return []checkpointDetail{detail}
   300→}
