   302→// gatherCheckpointDetails extracts detailed information for each checkpoint.
   303→// Checkpoints come in newest-first order, but we number them oldest=1, newest=N.
   304→func gatherCheckpointDetails(strat strategy.Strategy, session *strategy.Session) []checkpointDetail {
   305→	details := make([]checkpointDetail, 0, len(session.Checkpoints))
   306→	total := len(session.Checkpoints)
   307→
   308→	for i, cp := range session.Checkpoints {
   309→		detail := checkpointDetail{
   310→			Index:            total - i, // Reverse numbering: oldest=1, newest=N
   311→			Timestamp:        cp.Timestamp,
   312→			IsTaskCheckpoint: cp.IsTaskCheckpoint,
   313→			Message:          cp.Message,
   314→		}
   315→
   316→		// Use checkpoint ID for display (truncate long IDs)
   317→		detail.ShortID = cp.CheckpointID
   318→		if len(detail.ShortID) > 12 {
   319→			detail.ShortID = detail.ShortID[:12]
   320→		}
   321→
   322→		// Try to get transcript for this checkpoint
   323→		transcriptContent, err := strat.GetCheckpointLog(cp)
   324→		if err == nil {
   325→			transcript, parseErr := parseTranscriptFromBytes(transcriptContent)
   326→			if parseErr == nil {
   327→				// Extract all prompt/response pairs from the transcript
   328→				pairs := ExtractAllPromptResponses(transcript)
   329→				for _, pair := range pairs {
   330→					detail.Interactions = append(detail.Interactions, interaction(pair))
   331→				}
   332→
   333→				// Aggregate all files for the checkpoint
   334→				fileSet := make(map[string]bool)
   335→				for _, pair := range pairs {
   336→					for _, f := range pair.Files {
   337→						if !fileSet[f] {
   338→							fileSet[f] = true
   339→							detail.Files = append(detail.Files, f)
   340→						}
   341→					}
   342→				}
   343→			}
   344→		}
   345→
   346→		details = append(details, detail)
   347→	}
   348→
   349→	return details
   350→}
