   352→// runExplainCommit explains a specific commit.
   353→func runExplainCommit(w io.Writer, commitRef string) error {
   354→	repo, err := openRepository()
   355→	if err != nil {
   356→		return fmt.Errorf("not a git repository: %w", err)
   357→	}
   358→
   359→	// Resolve the commit reference
   360→	hash, err := repo.ResolveRevision(plumbing.Revision(commitRef))
   361→	if err != nil {
   362→		return fmt.Errorf("commit not found: %s", commitRef)
   363→	}
   364→
   365→	commit, err := repo.CommitObject(*hash)
   366→	if err != nil {
   367→		return fmt.Errorf("failed to get commit: %w", err)
   368→	}
   369→
   370→	// Get files changed in this commit (diff from parent to current)
   371→	var files []string
   372→	commitTree, err := commit.Tree()
   373→	if err == nil && commit.NumParents() > 0 {
   374→		parent, parentErr := commit.Parent(0)
   375→		if parentErr == nil {
   376→			parentTree, treeErr := parent.Tree()
   377→			if treeErr == nil {
   378→				// Diff from parent to current commit to show what changed
   379→				changes, diffErr := parentTree.Diff(commitTree)
   380→				if diffErr == nil {
   381→					for _, change := range changes {
   382→						name := change.To.Name
   383→						if name == "" {
   384→							name = change.From.Name
   385→						}
   386→						files = append(files, name)
   387→					}
   388→				}
   389→			}
   390→		}
   391→	}
   392→
   393→	// Check for Entire metadata
   394→	metadataDir, hasMetadata := paths.ParseMetadataTrailer(commit.Message)
   395→	sessionID, hasSession := paths.ParseSessionTrailer(commit.Message)
   396→
   397→	// If no session trailer, try to extract from metadata path.
   398→	// Note: extractSessionIDFromMetadata is defined in rewind.go as it's used
   399→	// by both the rewind and explain commands for parsing metadata paths.
   400→	if !hasSession && hasMetadata {
   401→		sessionID = extractSessionIDFromMetadata(metadataDir)
   402→		hasSession = sessionID != ""
   403→	}
   404→
   405→	// Build commit info
   406→	fullSHA := hash.String()
   407→	shortSHA := fullSHA
   408→	if len(fullSHA) >= 7 {
   409→		shortSHA = fullSHA[:7]
   410→	}
   411→
   412→	info := &commitInfo{
   413→		SHA:       fullSHA,
   414→		ShortSHA:  shortSHA,
   415→		Message:   strings.Split(commit.Message, "\n")[0], // First line only
   416→		Author:    commit.Author.Name,
   417→		Email:     commit.Author.Email,
   418→		Date:      commit.Author.When,
   419→		Files:     files,
   420→		HasEntire: hasMetadata || hasSession,
   421→		SessionID: sessionID,
   422→	}
   423→
   424→	// Format and output
   425→	output := formatCommitInfo(info)
   426→	fmt.Fprint(w, output)
   427→
   428→	return nil
   429→}
