   431→// formatSessionInfo formats session information for display.
   432→func formatSessionInfo(session *strategy.Session, sourceRef string, checkpoints []checkpointDetail) string {
   433→	var sb strings.Builder
   434→
   435→	// Session header
   436→	sb.WriteString(fmt.Sprintf("Session: %s\n", session.ID))
   437→	sb.WriteString(fmt.Sprintf("Strategy: %s\n", session.Strategy))
   438→
   439→	if !session.StartTime.IsZero() {
   440→		sb.WriteString(fmt.Sprintf("Started: %s\n", session.StartTime.Format("2006-01-02 15:04:05")))
   441→	}
   442→
   443→	if sourceRef != "" {
   444→		sb.WriteString(fmt.Sprintf("Source Ref: %s\n", sourceRef))
   445→	}
   446→
   447→	sb.WriteString(fmt.Sprintf("Checkpoints: %d\n", len(checkpoints)))
   448→
   449→	// Checkpoint details
   450→	for _, cp := range checkpoints {
   451→		sb.WriteString("\n")
   452→
   453→		// Checkpoint header
   454→		taskMarker := ""
   455→		if cp.IsTaskCheckpoint {
   456→			taskMarker = " [Task]"
   457→		}
   458→		sb.WriteString(fmt.Sprintf("─── Checkpoint %d [%s] %s%s ───\n",
   459→			cp.Index, cp.ShortID, cp.Timestamp.Format("2006-01-02 15:04"), taskMarker))
   460→		sb.WriteString("\n")
   461→
   462→		// Display all interactions in this checkpoint
   463→		for i, inter := range cp.Interactions {
   464→			// For multiple interactions, add a sub-header
   465→			if len(cp.Interactions) > 1 {
   466→				sb.WriteString(fmt.Sprintf("### Interaction %d\n\n", i+1))
   467→			}
   468→
   469→			// Prompt section
   470→			if inter.Prompt != "" {
   471→				sb.WriteString("## Prompt\n\n")
   472→				sb.WriteString(inter.Prompt)
   473→				sb.WriteString("\n\n")
   474→			}
   475→
   476→			// Response section
   477→			if len(inter.Responses) > 0 {
   478→				sb.WriteString("## Responses\n\n")
   479→				sb.WriteString(strings.Join(inter.Responses, "\n\n"))
   480→				sb.WriteString("\n\n")
   481→			}
   482→
   483→			// Files modified for this interaction
   484→			if len(inter.Files) > 0 {
   485→				sb.WriteString(fmt.Sprintf("Files Modified (%d):\n", len(inter.Files)))
   486→				for _, file := range inter.Files {
   487→					sb.WriteString(fmt.Sprintf("  - %s\n", file))
   488→				}
   489→				sb.WriteString("\n")
   490→			}
   491→		}
   492→
   493→		// If no interactions, show message and/or files
   494→		if len(cp.Interactions) == 0 {
   495→			// Show commit message as summary when no transcript available
   496→			if cp.Message != "" {
   497→				sb.WriteString(cp.Message)
   498→				sb.WriteString("\n\n")
   499→			}
   500→			// Show aggregate files if available
   501→			if len(cp.Files) > 0 {
   502→				sb.WriteString(fmt.Sprintf("Files Modified (%d):\n", len(cp.Files)))
   503→				for _, file := range cp.Files {
   504→					sb.WriteString(fmt.Sprintf("  - %s\n", file))
   505→				}
   506→			}
   507→		}
   508→	}
   509→
   510→	return sb.String()
   511→}
