   513→// formatCommitInfo formats commit information for display.
   514→func formatCommitInfo(info *commitInfo) string {
   515→	var sb strings.Builder
   516→
   517→	sb.WriteString(fmt.Sprintf("Commit: %s (%s)\n", info.SHA, info.ShortSHA))
   518→	sb.WriteString(fmt.Sprintf("Date: %s\n", info.Date.Format("2006-01-02 15:04:05")))
   519→
   520→	if info.HasEntire && info.SessionID != "" {
   521→		sb.WriteString(fmt.Sprintf("Session: %s\n", info.SessionID))
   522→	}
   523→
   524→	sb.WriteString("\n")
   525→
   526→	// Message
   527→	sb.WriteString("Message:\n")
   528→	sb.WriteString(fmt.Sprintf("  %s\n", info.Message))
   529→	sb.WriteString("\n")
   530→
   531→	// Files modified
   532→	if len(info.Files) > 0 {
   533→		sb.WriteString(fmt.Sprintf("Files Modified (%d):\n", len(info.Files)))
   534→		for _, file := range info.Files {
   535→			sb.WriteString(fmt.Sprintf("  - %s\n", file))
   536→		}
   537→		sb.WriteString("\n")
   538→	}
   539→
   540→	// Note for non-Entire commits
   541→	if !info.HasEntire {
   542→		sb.WriteString("Note: No Entire session data available for this commit.\n")
   543→	}
   544→
   545→	return sb.String()
   546→}
