   548→// outputWithPager outputs content through a pager if stdout is a terminal and content is long.
   549→func outputWithPager(w io.Writer, content string) {
   550→	// Check if we're writing to stdout and it's a terminal
   551→	if f, ok := w.(*os.File); ok && f == os.Stdout && term.IsTerminal(int(f.Fd())) {
   552→		// Get terminal height
   553→		_, height, err := term.GetSize(int(f.Fd()))
   554→		if err != nil {
   555→			height = 24 // Default fallback
   556→		}
   557→
   558→		// Count lines in content
   559→		lineCount := strings.Count(content, "\n")
   560→
   561→		// Use pager if content exceeds terminal height
   562→		if lineCount > height-2 {
   563→			pager := os.Getenv("PAGER")
   564→			if pager == "" {
   565→				pager = "less"
   566→			}
   567→
   568→			cmd := exec.CommandContext(context.Background(), pager) //nolint:gosec // pager from env is expected
   569→			cmd.Stdin = strings.NewReader(content)
   570→			cmd.Stdout = f
   571→			cmd.Stderr = os.Stderr
   572→
   573→			if err := cmd.Run(); err != nil {
   574→				// Fallback to direct output if pager fails
   575→				fmt.Fprint(w, content)
   576→			}
   577→			return
   578→		}
   579→	}
   580→
   581→	// Direct output for non-terminal or short content
   582→	fmt.Fprint(w, content)
   583→}
